   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="羞赧的红晕爬上了闪蝶的耳尖，她下意识吃了一口三明治，不敢看泽菲琳。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_602.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4522", 0, 0, 2.5, 223},{ 3, "4526", 0, 0, 25, 226}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="嗯，我喜欢链尉官，是他把我带出了人生的阴影……他是我最重要的人。", msg_color="", msg_size=0, talker="闪蝶", audio="", img="arts/ui/bg/story/storybg_602.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4522", 0, 0, 2.5, 223},{ 3, "4526", 0, 0, 25, 226}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
