   [55]={next_id=56, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="原来是这样吗？那前辈对那里一定很熟悉了。", msg_color="", msg_size=0, talker="泽菲琳", audio="", img="arts/ui/bg/story/storybg_602.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4522", 0, 0, 2.5, 223},{ 3, "4526", 0, 0, 25, 226}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [56]={next_id=57, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="看着泽菲琳充满了好奇的眼神，闪蝶苦笑地摇摇头。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_602.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4522", 0, 0, 2.5, 223},{ 3, "4526", 0, 0, 25, 226}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [57]={next_id=58, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="虽然是我的故乡，但我一直待在实验室里没有出来，所以其实没有怎么了解过。", msg_color="", msg_size=0, talker="闪蝶", audio="", img="arts/ui/bg/story/storybg_602.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4522", 0, 0, 2.5, 223},{ 3, "4526", 0, 0, 25, 226}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [58]={next_id=59, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="听那些大人们说，伯基索米是一个由大统领领导的强大帝国，拥有很强大的军队，还有神光重科这样厉害的军工企业。", msg_color="", msg_size=0, talker="闪蝶", audio="", img="arts/ui/bg/story/storybg_602.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4522", 0, 0, 2.5, 223},{ 3, "4526", 0, 0, 25, 226}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [59]={next_id=60, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="对了，妈妈还说过，伯基索米没有不听大统领话的人，她的意志延伸到帝国的每一寸土地，贯穿了“铁与血”的诠释……", msg_color="", msg_size=0, talker="闪蝶", audio="", img="arts/ui/bg/story/storybg_602.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4522", 0, 0, 2.5, 223},{ 3, "4526", 0, 0, 25, 226}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [60]={next_id=61, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="感觉……似乎是一个很严肃的地方呢。大统领这么厉害，能够让所有人都听她的话吗？", msg_color="", msg_size=0, talker="泽菲琳", audio="", img="arts/ui/bg/story/storybg_602.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4522", 0, 0, 2.5, 223},{ 3, "4526", 0, 0, 25, 226}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [61]={next_id=62, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="嗯，不过我也没见过大统领，不知道她是一个怎样的人，只知道军队都以她的命令为主，神光重科也总是会以她的需求进行装备研发。", msg_color="", msg_size=0, talker="闪蝶", audio="", img="arts/ui/bg/story/storybg_602.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4522", 0, 0, 2.5, 223},{ 3, "4526", 0, 0, 25, 226}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [62]={next_id=63, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="闪蝶絮絮叨叨地说着，而泽菲琳已经露出了“听不懂”的表情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_602.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "4522", 0, 0, 2.5, 223},{ 3, "4526", 0, 0, 25, 226}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
