   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="关于狮刃的过往，在莱斯坦斯一直是一个鲜少被提起的事情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="虽然你拥有查看战员档案的权限，但狮刃的档案里只提及了她从伯基索米而来，因一场军事行动而放弃了军籍，经引荐来到莱斯坦斯担任新人教官一职。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所谓的军事行动并未有详细记载，然而经过这段时间的相处，你大概能猜到，或许就和弦枝口中的“伊凡城暴动”有关。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但她从未提及过这件事，老实说，你甚至不能确定她答应做你们的向导原因是什么。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =5, dialog=0, msg="黑屏转场", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="arts/storyPrefab/prefab/common/prefab/StoryMask.prefab", runTalkTime =1000, destoryTime =3000, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [95]={next_id=96, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们到了。这里就是禁区。", msg_color="", msg_size=0, talker="狮刃", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3102", 0, 0, 49, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [96]={next_id=97, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这里……和伊凡城好像没有什么特别大的区别。", msg_color="", msg_size=0, talker="艾丽西亚", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101_1", 0, 0, 8, 176.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="随着众人停下脚步，你看清了眼前的景象：一片被积雪掩埋的废弃城区，断壁残垣上爬满枯藤，锈迹斑斑的设施歪歪斜斜地立在雪中，像一群沉默的亡魂。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一旁的警告牌早已被风雪侵蚀，却仍能清晰辨认出暗红色的字迹——“污染禁区，严禁踏入”。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在皑皑白雪的映衬下，这些字样透着森然的寒意。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="有房屋、也有街道，原来禁区是指一整片废弃的城区？", msg_color="", msg_size=0, talker="艾丽西亚", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101_1", 0, 0, 8, 176.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="嗯，因为当年暴动发生的事故，导致这一片城区都被虚粒子污染覆盖，卫队没有办法收复这里，最终选择了封锁放弃。", msg_color="", msg_size=0, talker="狮刃", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3102", 0, 0, 49, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [102]={next_id=103, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……过了这么多年，这里还是老样子。", msg_color="", msg_size=0, talker="狮刃", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3102", 0, 0, 49, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [103]={next_id=104, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="狮刃看向风雪中的一座建筑，它的风格与现在的伊凡城完全不同，外形独特，颜色艳丽，仿佛来自另一个文明。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
