   [202]={next_id=203, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那棵巨树，又一次闯入了你的意识。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_112.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [203]={next_id=204, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不同于以往的模糊碎片，这次的画面无比清晰——苍劲的枝干遮天蔽日，树下的福光温暖却带着致命的吸力，无数细碎的黑影在光中蠕动，像是在朝拜，又像是在哭泣。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_112.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
